sys_variable_value.value:
(function execute(inputs, outputs) {
       var r = new sn_ws.RESTMessageV2('Jira - Update Custom Fields', 'PUT Update Issue');
       r.setStringParameterNoEscape('issue_key', inputs.issue_key);

       var payload = {
           fields: {
               customfield_10142: inputs.business_justification,
               customfield_10141: inputs.acceptance_criteria
           }
       };
       r.setRequestBody(JSON.stringify(payload));

       var response = r.execute();
       outputs.status_code = response.getStatusCode();
       outputs.response_body = response.getBody();
   })(inputs, outputs);

